import{_ as r,a0 as s,w as i,s as d,ao as p,I as a,x as u,a1 as e,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse(`{"title":"Linux有问必答：如何更新过期版本的Ubuntu | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：如何更新过期版本的Ubuntu | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：如何更新过期版本的Ubuntu | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：如何更新过期版本的Ubuntu | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150518 Linux FAQs with Answers--How to fix '404 Not Found' error with 'apt-get update' on old Ubuntu","title":"Linux有问必答：如何更新过期版本的Ubuntu","tag":"201506","desc":""},"relativePath":"201506/20150518 Linux FAQs with Answers--How to fix '404 Not Found' error with 'apt-get update' on old Ubuntu.md","filePath":"[post].md"}`),l={name:"201506/20150518 Linux FAQs with Answers--How to fix '404 Not Found' error with 'apt-get update' on old Ubuntu.md"};function b(m,t,x,f,g,c){const n=s("Link");return i(),d("div",null,[t[13]||(t[13]=p(`<h1 id="linux有问必答-如何更新过期版本的ubuntu" tabindex="-1">Linux有问必答：如何更新过期版本的Ubuntu <a class="header-anchor" href="#linux有问必答-如何更新过期版本的ubuntu" aria-label="Permalink to “Linux有问必答：如何更新过期版本的Ubuntu”">​</a></h1><blockquote><p><strong>问题</strong>： 我的PC上安装了旧版的Ubuntu 13.04（急切的浣熊）。当我在上面运行“sudo apt-get update”时，它丢给了我一大堆“404 Not Found”错误，结果是我不能使用apt-get或aptitude来安装或更新任何软件包了。由于该错误的原因，我甚至不能将它升级到更新的版本。我怎样才能修复这个问题啊？</p></blockquote><p><img src="https://farm6.staticflickr.com/5460/17634085636_996b2a8ab5_b.jpg" alt=""></p><p>每个Ubuntu版本都有生命结束周期（EOL）时间；常规的Ubuntu发行版提供18个月的支持，而LTS（长期支持）版本则长达3年（服务器版本）和5年（桌面版本）。当某个Ubuntu版本达到生命结束周期时，其仓库就不能再访问了，你也不能再从Canonical获取任何维护更新和安全补丁。在撰写本文时，Ubuntu 13.04（急切的浣熊）已经达到了它的生命结束周期。</p><p>如果你所使用的Ubuntu系统已经被结束生命周期，你就会从apt-get或aptitude得到以下404错误，因为它的仓库已经被遗弃了。</p><pre><code>W: Failed to fetch http://us.archive.ubuntu.com/ubuntu/dists/raring-backports/multiverse/binary-i386/Packages  404  Not Found [IP: 91.189.91.13 80]

W: Failed to fetch http://extras.ubuntu.com/ubuntu/dists/raring/main/binary-amd64/Packages  404  Not Found

W: Failed to fetch http://security.ubuntu.com/ubuntu/dists/raring-security/universe/binary-i386/Packages  404  Not Found [IP: 91.189.88.149 80]

E: Some index files failed to download. They have been ignored, or old ones used instead
</code></pre><p>对于那些还在使用旧版本Ubuntu的用户，Canonical维护了一个old-releases.ubuntu.com的网站，这里包含了结束生命周期的仓库归档。因此，当Canonical对你安装的Ubuntu版本结束支持时，你需要将仓库切换到old-releases.ubuntu.com（除非你在结束生命周期之前想要升级）。</p><p>这里，通过切换到旧版本仓库提供了一个快速修复“404 Not Found”错误的便捷方式。</p><p>首先，使用old-releases仓库替换main/security仓库，就像下面这样。</p><pre><code>$ sudo sed -i -r &#39;s/([a-z]{2}\\.)?archive.ubuntu.com/old-releases.ubuntu.com/g&#39; /etc/apt/sources.list
$ sudo sed -i -r &#39;s/security.ubuntu.com/old-releases.ubuntu.com/g&#39; /etc/apt/sources.list
</code></pre><p>然后，使用文本编辑器打开/etc/apt/sources.list，并查找extras.ubuntu.com。该仓库也不再支持Ubuntu 13.04了，所以你需要使用“#”号将extras.ubuntu.com注释掉。</p><pre><code>#deb http://extras.ubuntu.com/ubuntu raring main
#deb-src http://extras.ubuntu.com/ubuntu raring main
</code></pre><p>现在，你应该可以在旧版不受支持的Ubuntu上安装或更新软件包了。</p><hr>`,14)),a("p",null,[t[1]||(t[1]=u("via: ",-1)),e(n,{href:"http://ask.xmodulo.com/404-not-found-error-apt-get-update-ubuntu.html"},{default:o(()=>[...t[0]||(t[0]=[u("http://ask.xmodulo.com/404-not-found-error-apt-get-update-ubuntu.html",-1)])]),_:1})]),a("p",null,[t[5]||(t[5]=u("作者：",-1)),e(n,{href:"http://ask.xmodulo.com/author/nanni"},{default:o(()=>[...t[2]||(t[2]=[u("Dan Nanni",-1)])]),_:1}),t[6]||(t[6]=u(" 译者：",-1)),e(n,{href:"https://github.com/GOLinux"},{default:o(()=>[...t[3]||(t[3]=[u("GOLinux",-1)])]),_:1}),t[7]||(t[7]=u(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[4]||(t[4]=[u("wxy",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=u("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[8]||(t[8]=[u("LCTT",-1)])]),_:1}),t[11]||(t[11]=u(" 原创翻译，",-1)),e(n,{href:"https://linux.cn/"},{default:o(()=>[...t[9]||(t[9]=[u("Linux中国",-1)])]),_:1}),t[12]||(t[12]=u(" 荣誉推出",-1))])])}const h=r(l,[["render",b]]);export{T as __pageData,h as default};
